    10	    }
    11	
    12	
    13	    public abstract static class PorTransportadora implements ModalidadeEntrega {
    14	
    15	        private final Transportadora transportadora;
    16	        private final String codigo;
    17	
    18	        protected PorTransportadora(Transportadora transportadora, String codigo) {
    19	            this.transportadora = transportadora;
    20	            this.codigo = codigo;
