    17	            return "BEMVINDO10";
    18	        }
    19	
    20	        @Override
    21	        public Optional<BigDecimal> desconto(Contexto c) {
    22	            if (!c.primeiraCompra().getAsBoolean()) {
    23	                return Optional.empty();
    24	            }
    25	            return Optional.of(Dinheiro.porcentagem(c.subtotalProdutos(), "0.10"));
