    35	
    36	        @Override
    37	        public Optional<BigDecimal> desconto(Contexto c) {
    38	            if (c.subtotalProdutos().compareTo(Dinheiro.de("300.00")) < 0) {
    39	                return Optional.empty();
    40	            }
    41	            return Optional.of(Dinheiro.de("50.00"));
    42	        }
    43	    }
