    48	        public String codigo() {
    49	            return "FRETEGRATIS";
    50	        }
    51	
    52	        @Override
    53	        public Optional<BigDecimal> desconto(Contexto c) {
    54	            if ("RETIRADA_LOJA".equals(c.modalidade())) {
    55	                return Optional.empty();
    56	            }
    57	            return Optional.of(c.frete());
    58	        }
    59	    }
    60	
    61	    @Component
    62	    public static class Leve3Pague2 implements Cupom {
    63	        @Override
    64	        public String codigo() {
    65	            return "LEVE3PAGUE2";
    66	        }
    67	
    68	        @Override
    69	        public Optional<BigDecimal> desconto(Contexto c) {
    70	            BigDecimal total = Dinheiro.ZERO;
    71	            for (Linha l : c.linhas()) {
    72	                total = total.add(l.preco().multiply(BigDecimal.valueOf(l.quantidade() / 3)));
    73	            }
    74	            if (total.signum() == 0) {
    75	                return Optional.empty();
    76	            }
    77	            return Optional.of(Dinheiro.arredondar(total));
    78	        }
