     1	package com.loja.dominio;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.MathContext;
     5	import java.math.RoundingMode;
     6	
     7	import org.springframework.stereotype.Component;
     8	
     9	public final class FormasPagamento {
    10	
    11	    private FormasPagamento() {
    12	    }
    13	
    14	    @Component
    15	    public static class Pix implements FormaPagamento {
    16	        @Override
    17	        public String codigo() {
    18	            return "PIX";
    19	        }
    20	
    21	        @Override
    22	        public boolean parcelasPermitidas(int parcelas) {
    23	            return parcelas == 1;
    24	        }
    25	
    26	        @Override
    27	        public Resultado calcular(BigDecimal total, int parcelas, boolean usouCupom) {
    28	            BigDecimal desconto = usouCupom ? Dinheiro.ZERO : Dinheiro.porcentagem(total, "0.05");
    29	            BigDecimal finalPix = Dinheiro.arredondar(total.subtract(desconto));
    30	            return new Resultado(finalPix, finalPix);
    31	        }
    32	    }
    33	
    34	    @Component
    35	    public static class Boleto implements FormaPagamento {
    36	
    37	        private static final BigDecimal LIMITE = Dinheiro.de("1000.00");
    38	
    39	        @Override
    40	        public String codigo() {
    41	            return "BOLETO";
    42	        }
    43	
    44	        @Override
    45	        public boolean parcelasPermitidas(int parcelas) {
    46	            return parcelas == 1;
    47	        }
    48	
    49	        @Override
    50	        public boolean disponivel(BigDecimal totalPedido) {
    51	            return totalPedido.compareTo(LIMITE) <= 0;
    52	        }
    53	
    54	        @Override
    55	        public Resultado calcular(BigDecimal total, int parcelas, boolean usouCupom) {
    56	            BigDecimal finalBoleto = Dinheiro.arredondar(total.add(Dinheiro.de("3.49")));
    57	            return new Resultado(finalBoleto, finalBoleto);
    58	        }
    59	    }
    60	
    61	    @Component
    62	    public static class Cartao implements FormaPagamento {
    63	
    64	        private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
    65	        private static final MathContext PRECISAO = new MathContext(40);
    66	
    67	        @Override
    68	        public String codigo() {
    69	            return "CARTAO";
    70	        }
    71	
    72	        @Override
    73	        public boolean parcelasPermitidas(int parcelas) {
    74	            return parcelas >= 1 && parcelas <= 12;
    75	        }
    76	
    77	        @Override
    78	        public Resultado calcular(BigDecimal total, int parcelas, boolean usouCupom) {
    79	            BigDecimal n = BigDecimal.valueOf(parcelas);
    80	            if (parcelas <= 3) {
    81	                return new Resultado(total, total.divide(n, 2, RoundingMode.HALF_EVEN));
    82	            }
    83	
    84	            BigDecimal potencia = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas, PRECISAO);
    85	            BigDecimal fator = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(potencia, PRECISAO));
    86	            BigDecimal parcela = Dinheiro.arredondar(total.multiply(TAXA_MENSAL).divide(fator, PRECISAO));
    87	            return new Resultado(Dinheiro.arredondar(parcela.multiply(n)), parcela);
    88	        }
    89	    }
    90	}
