     1	package com.loja.dominio;
     2	
     3	import java.math.BigDecimal;
     4	
     5	public enum Regiao {
     6	    SUDESTE("0.01", null, 0),
     7	    SUL("0.01", null, 0),
     8	    CENTRO_OESTE("0.015", null, 0),
     9	    NORTE("0.025", "30.00", 3),
    10	    NORDESTE("0.02", "30.00", 2);
    11	
    12	    private final String taxaSeguro;
    13	    private final BigDecimal limiteSeguro;
    14	    private final int diasExtraDespacho;
    15	
    16	    Regiao(String taxaSeguro, String limiteSeguro, int diasExtraDespacho) {
    17	        this.taxaSeguro = taxaSeguro;
    18	        this.limiteSeguro = limiteSeguro == null ? null : Dinheiro.de(limiteSeguro);
    19	        this.diasExtraDespacho = diasExtraDespacho;
    20	    }
    21	
    22	    public int diasExtraDespacho() {
    23	        return diasExtraDespacho;
    24	    }
    25	
    26	    public BigDecimal seguro(BigDecimal subtotalProdutos) {
    27	        BigDecimal valor = Dinheiro.porcentagem(subtotalProdutos, taxaSeguro);
    28	        if (limiteSeguro != null && valor.compareTo(limiteSeguro) > 0) {
    29	            return limiteSeguro;
    30	        }
    31	        return valor;
    32	    }
    33	
    34	    public static Regiao de(String texto) {
    35	        if (texto == null) {
    36	            return null;
    37	        }
    38	        for (Regiao r : values()) {
    39	            if (r.name().equals(texto)) {
    40	                return r;
    41	            }
    42	        }
    43	        return null;
    44	    }
    45	}

