    52	        List<Item> itens = new ArrayList<>();
    53	        for (DadosCompra.ItemDados item : dados.itens()) {
    54	            if (item == null || vazio(item.sku()) || !vistos.add(item.sku())
    55	                    || item.quantidade() == null || item.quantidade() <= 0) {
    56	                throw ErroNegocio.invalido("PEDIDO_INVALIDO");
    57	            }
    58	            itens.add(new Item(item.sku(), item.quantidade()));
    59	        }
