   102	        if (modalidade == null) {
   103	            throw ErroNegocio.invalido("MODALIDADE_INVALIDA");
   104	        }
   105	
   106	        BigDecimal subtotal = Dinheiro.ZERO;
   107	        BigDecimal peso = BigDecimal.ZERO;
   108	        List<Cupom.Linha> linhas = new ArrayList<>();
   109	        for (Item item : itens) {
   110	            Disponivel p = catalogo.get(item.sku());
   111	            BigDecimal quantidade = BigDecimal.valueOf(item.quantidade());
   112	            subtotal = subtotal.add(p.preco().multiply(quantidade));
   113	            peso = peso.add(p.pesoKg().multiply(quantidade));
   114	            linhas.add(new Cupom.Linha(p.sku(), p.preco(), item.quantidade()));
   115	        }
   116	        subtotal = Dinheiro.arredondar(subtotal);
