   128	            if (cupom == null) {
   129	                throw ErroNegocio.invalido("CUPOM_INVALIDO");
   130	            }
   131	            Cupom.Contexto contexto = new Cupom.Contexto(linhas, subtotal, frete, modalidade.codigo(),
   132	                    () -> primeiraCompra(cpf));
   133	            Optional<BigDecimal> desconto = cupom.desconto(contexto);
