   135	                    .orElseThrow(() -> ErroNegocio.invalido("CUPOM_NAO_APLICAVEL")));
   136	        }
   137	
   138	        BigDecimal seguro = regiao.seguro(subtotal);
   139	        BigDecimal total = Dinheiro.arredondar(subtotal.subtract(descontoCupom).add(frete).add(seguro));
   140	
   141	
   142	        FormaPagamento forma = dados.formaPagamento() == null ? null : formas.get(dados.formaPagamento());
   143	        if (forma == null) {
   144	            throw ErroNegocio.invalido("FORMA_PAGAMENTO_INVALIDA");
   145	        }
   146	        int parcelas = dados.parcelas() == null ? 1 : dados.parcelas();
   147	        if (!forma.parcelasPermitidas(parcelas)) {
   148	            throw ErroNegocio.invalido("PARCELAMENTO_INVALIDO");
   149	        }
   150	        if (!forma.disponivel(total)) {
   151	            throw ErroNegocio.invalido("FORMA_PAGAMENTO_INDISPONIVEL");
   152	        }
   153	        FormaPagamento.Resultado pagamento = forma.calcular(total, parcelas, usouCupom);
   154	
   155	        Resumo resumo = new Resumo(
   156	                subtotal,
   157	                descontoCupom,
   158	                frete,
   159	                cotacao.prazoDias(),
   160	                seguro,
   161	                Dinheiro.arredondar(pagamento.totalFinal().subtract(total)),
   162	                pagamento.totalFinal(),
   163	                parcelas,
   164	                pagamento.valorParcela(),
   165	                Dinheiro.porcentagem(subtotal, nivel.taxaCredito()),
   166	                nivel.brinde(subtotal));
   167	        return new Calculo(resumo, itens);
   168	    }
   169	
   170	    private boolean primeiraCompra(String cpf) {
   171	        return armazem.ler(estado -> estado.pedidosDoCliente(cpf).stream().noneMatch(p ->
   172	                p.situacao() == SituacaoPedido.PAGO || p.situacao() == SituacaoPedido.ENVIADO
   173	                        || p.situacao() == SituacaoPedido.ENTREGUE));
