   160	                seguro,
   161	                Dinheiro.arredondar(pagamento.totalFinal().subtract(total)),
   162	                pagamento.totalFinal(),
   163	                parcelas,
   164	                pagamento.valorParcela(),
   165	                Dinheiro.porcentagem(subtotal, nivel.taxaCredito()),
   166	                nivel.brinde(subtotal));
   167	        return new Calculo(resumo, itens);
   168	    }
