   170	    private boolean primeiraCompra(String cpf) {
   171	        return armazem.ler(estado -> estado.pedidosDoCliente(cpf).stream().noneMatch(p ->
   172	                p.situacao() == SituacaoPedido.PAGO || p.situacao() == SituacaoPedido.ENVIADO
   173	                        || p.situacao() == SituacaoPedido.ENTREGUE));
   174	    }
