    36	    public Pedido registrar(DadosCompra dados) {
    37	        CalculadoraResumo.Calculo calculo = calculadora.calcular(dados);
    38	        return armazem.escrever((estado, mudancas) -> {
    39	            String cpf = dados.cliente().cpf();
    40	            if (!estado.clientes.containsKey(cpf)) {
    41	                Cliente cliente = new Cliente(cpf, dados.cliente().email(), Dinheiro.ZERO);
    42	                estado.clientes.put(cpf, cliente);
    43	                mudancas.clientes.add(cliente);
    44	            }
    45	            Pedido pedido = new Pedido(UUID.randomUUID().toString(), cpf, SituacaoPedido.AGUARDANDO_PAGAMENTO,
    46	                    Instant.now(relogio).truncatedTo(ChronoUnit.SECONDS), calculo.resumo(), calculo.itens(),
    47	                    null, null);
    48	            estado.adicionarPedido(pedido);
    49	            mudancas.pedidos.add(pedido);
    50	            return pedido.copia();
    51	        });
    52	    }
