    58	    public Pedido pagar(String id, String idTransacao, String pagoEmTexto) {
    59	        return armazem.escrever((estado, mudancas) -> {
    60	            Pedido pedido = buscar(estado, id);
    61	            if (idTransacao != null && idTransacao.equals(pedido.idTransacao())
    62	                    && pedido.situacao() != SituacaoPedido.AGUARDANDO_PAGAMENTO) {
    63	                return pedido.copia();
    64	            }
    65	            if (!pedido.situacao().permite(SituacaoPedido.PAGO)) {
    66	                throw ErroNegocio.conflito("OPERACAO_NAO_PERMITIDA");
    67	            }
    68	            if (idTransacao == null || idTransacao.isBlank()) {
    69	                throw ErroNegocio.invalido("PEDIDO_INVALIDO");
    70	            }
    71	            Instant momento = momento(pagoEmTexto);
    72	            if (Duration.between(pedido.criadoEm(), momento).compareTo(PRAZO_PAGAMENTO) > 0) {
    73	                cancelarInterno(estado, mudancas, pedido);
    74	                throw ErroNegocio.conflito("PEDIDO_EXPIRADO");
    75	            }
    76	            for (Item item : pedido.itens()) {
    77	                if (estado.produtos.get(item.sku()).estoque() < item.quantidade()) {
    78	                    cancelarInterno(estado, mudancas, pedido);
    79	                    throw ErroNegocio.conflito("ESTOQUE_INSUFICIENTE");
    80	                }
    81	            }
    82	            for (Item item : pedido.itens()) {
    83	                Produto produto = estado.produtos.get(item.sku());
    84	                produto.baixar(item.quantidade());
    85	                mudancas.produtos.add(produto);
    86	            }
    87	            pedido.registrarPagamento(idTransacao);
    88	            mudancas.pedidos.add(pedido);
    89	            efeitos.forEach(e -> e.aplicar(estado, mudancas, pedido));
    90	            avisar(estado, mudancas, pedido, TipoAviso.PAGAMENTO_APROVADO);
    91	            return pedido.copia();
    92	        });
    93	    }
