    98	            if (!pedido.situacao().permite(SituacaoPedido.ENVIADO)) {
    99	                throw ErroNegocio.conflito("OPERACAO_NAO_PERMITIDA");
   100	            }
   101	            if (codigoRastreio == null || codigoRastreio.isBlank()) {
   102	                throw ErroNegocio.invalido("PEDIDO_INVALIDO");
   103	            }
   104	            pedido.registrarEnvio(codigoRastreio);
   105	            mudancas.pedidos.add(pedido);
   106	            avisar(estado, mudancas, pedido, TipoAviso.PEDIDO_ENVIADO);
   107	            return pedido.copia();
   108	        });
   109	    }
   110	
   111	    public Pedido entregar(String id) {
   112	        return armazem.escrever((estado, mudancas) -> {
   113	            Pedido pedido = buscar(estado, id);
   114	            pedido.mudarPara(SituacaoPedido.ENTREGUE);
   115	            mudancas.pedidos.add(pedido);
   116	            return pedido.copia();
   117	        });
   118	    }
   119	
   120	    public Pedido cancelar(String id) {
   121	        return armazem.escrever((estado, mudancas) -> {
   122	            Pedido pedido = buscar(estado, id);
   123	            if (!pedido.situacao().permite(SituacaoPedido.CANCELADO)) {
   124	                throw ErroNegocio.conflito("OPERACAO_NAO_PERMITIDA");
   125	            }
   126	            cancelarInterno(estado, mudancas, pedido);
   127	            return pedido.copia();
   128	        });
   129	    }
