   131	    private Instant momento(String texto) {
   132	        if (texto == null) {
   133	            return Instant.now(relogio);
   134	        }
   135	        try {
   136	            return Instant.parse(texto);
   137	        } catch (java.time.format.DateTimeParseException e) {
   138	            throw ErroNegocio.invalido("PEDIDO_INVALIDO");
   139	        }
   140	    }
