   142	    private void cancelarInterno(Estado estado, Mudancas mudancas, Pedido pedido) {
   143	        if (pedido.situacao() == SituacaoPedido.PAGO) {
   144	            for (Item item : pedido.itens()) {
   145	                Produto produto = estado.produtos.get(item.sku());
   146	                produto.devolver(item.quantidade());
   147	                mudancas.produtos.add(produto);
   148	            }
   149	            efeitos.forEach(e -> e.reverter(estado, mudancas, pedido));
   150	        }
   151	        pedido.mudarPara(SituacaoPedido.CANCELADO);
   152	        mudancas.pedidos.add(pedido);
   153	        avisar(estado, mudancas, pedido, TipoAviso.PEDIDO_CANCELADO);
   154	    }
   155	
   156	    private void avisar(Estado estado, Mudancas mudancas, Pedido pedido, TipoAviso tipo) {
   157	        CanalNotificacao.Evento evento = new CanalNotificacao.Evento(pedido.cpf(), tipo, pedido.id());
   158	        canais.forEach(c -> c.notificar(estado, mudancas, evento));
   159	    }
   160	
   161	    private static Pedido buscar(Estado estado, String id) {
   162	        Pedido pedido = estado.pedidos.get(id);
   163	        if (pedido == null) {
   164	            throw ErroNegocio.naoEncontrado("PEDIDO_NAO_ENCONTRADO");
   165	        }
   166	        return pedido;
   167	    }
   168	}
