 26	@Component
 27	public class TransLogClient implements Transportadora {
 28	
 29	    private static final Logger log = LoggerFactory.getLogger(TransLogClient.class);
 30	    private static final Duration LIMITE = Duration.ofSeconds(2);
 31	
 32	    private final String urlBase;
 33	    private final HttpClient http = HttpClient.newBuilder().connectTimeout(LIMITE).build();
 34	    private final JsonMapper json = JsonMapper.builder()
 35	            .enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS).build();
 36	
 37	    public TransLogClient(@Value("${app.translog.url:}") String urlBase) {
 38	        this.urlBase = urlBase == null ? "" : urlBase.strip().replaceAll("/+$", "");
 39	    }
 40	
 41	    @Override
 42	    public Optional<Cotacao> cotar(String cep, BigDecimal pesoKg, String servico) {
 43	        if (urlBase.isEmpty()) {
 44	            throw foraDoAr("TRANSLOG_URL não definida", null);
 45	        }
 46	        URI uri = URI.create(urlBase + "/cotacao?cep=" + codificar(cep) + "&pesoKg=" + pesoKg.toPlainString()
 47	                + "&servico=" + codificar(servico));
 48	        HttpRequest requisicao = HttpRequest.newBuilder(uri).timeout(LIMITE).GET().build();
 49	        CompletableFuture<HttpResponse<String>> chamada = http.sendAsync(requisicao,
 50	                HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
 51	        HttpResponse<String> resposta;
 52	        try {
 53	            resposta = chamada.get(LIMITE.toMillis(), TimeUnit.MILLISECONDS);
 54	        } catch (InterruptedException e) {
 55	            chamada.cancel(true);
 56	            Thread.currentThread().interrupt();
 57	            throw foraDoAr("interrompido", e);
 58	        } catch (Exception e) {
 59	            chamada.cancel(true);
 60	            throw foraDoAr("sem resposta", e);
 61	        }
 62	        if (resposta.statusCode() == 404) {
 63	            return Optional.empty();
 64	        }
 65	        if (resposta.statusCode() != 200) {
 66	            throw foraDoAr("status " + resposta.statusCode(), null);
 67	        }
 68	        try {
 69	            JsonNode corpo = json.readTree(resposta.body());
 70	            JsonNode valor = corpo.get("valor");
 71	            JsonNode prazo = corpo.get("prazoDias");
 72	            if (valor == null || !valor.isNumber() || prazo == null || !prazo.isIntegralNumber()) {
 73	                throw foraDoAr("resposta inesperada", null);
 74	            }
 75	            return Optional.of(new Cotacao(valor.decimalValue(), prazo.intValue()));
 76	        } catch (ErroNegocio e) {
 77	            throw e;
 78	        } catch (RuntimeException e) {
 79	            throw foraDoAr("resposta ilegível", e);
 80	        }
 81	    }
 82	
 83	    private static String codificar(String texto) {
 84	        return URLEncoder.encode(texto, StandardCharsets.UTF_8);
 85	    }
 86	
 87	    private static ErroNegocio foraDoAr(String motivo, Exception causa) {
 88	        log.warn("TransLog indisponível: {}", motivo, causa);
 89	        return new ErroNegocio("TRANSPORTADORA_INDISPONIVEL", 503);
 90	    }
 91	}
