290	package com.loja.dominio;
291	
292	import java.util.concurrent.locks.ReentrantLock;
293	import java.util.function.BiFunction;
294	import java.util.function.Function;
295	
296	import org.slf4j.Logger;
297	import org.slf4j.LoggerFactory;
298	import org.springframework.stereotype.Component;
299	
300	
301	
302	
303	
304	@Component
305	public class Armazem {
306	
307	    private static final Logger log = LoggerFactory.getLogger(Armazem.class);
308	
309	    private final ReentrantLock trava = new ReentrantLock();
310	    private final Persistencia persistencia;
311	    private Estado estado;
312	
313	    public Armazem(Persistencia persistencia) {
314	        this.persistencia = persistencia;
315	        this.estado = persistencia.carregar();
316	    }
317	
318	    public <T> T ler(Function<Estado, T> leitura) {
319	        trava.lock();
320	        try {
321	            return leitura.apply(estado);
322	        } finally {
323	            trava.unlock();
324	        }
325	    }
326	
327	
328	
329	
330	
331	
332	    public <T> T escrever(BiFunction<Estado, Mudancas, T> alteracao) {
333	        trava.lock();
334	        try {
335	            Mudancas mudancas = new Mudancas();
336	            T resultado;
337	            try {
338	                resultado = alteracao.apply(estado, mudancas);
339	            } catch (ErroNegocio e) {
340	                gravarOuRecarregar(mudancas);
341	                throw e;
342	            } catch (RuntimeException e) {
343	                recarregar();
344	                throw e;
345	            }
346	            gravarOuRecarregar(mudancas);
347	            return resultado;
348	        } finally {
349	            trava.unlock();
350	        }
351	    }
352	
353	    private void gravarOuRecarregar(Mudancas mudancas) {
354	        if (mudancas.vazia()) {
355	            return;
356	        }
357	        try {
358	            persistencia.gravar(mudancas);
359	        } catch (RuntimeException e) {
360	            recarregar();
361	            throw e;
362	        }
363	    }
364	
365	    private void recarregar() {
366	        try {
367	            estado = persistencia.carregar();
368	        } catch (RuntimeException e) {
369	            log.error("Não foi possível recarregar o estado do banco", e);
370	        }
371	    }
372	}
373	package com.loja.dominio;
374	
375	public interface Persistencia {
376	
377	
378	    Estado carregar();
379	
380	
381	    void gravar(Mudancas mudancas);
382	}
383	package com.loja.dominio;
384	
385	import java.util.List;
386	
387	import org.springframework.stereotype.Service;
388	
389	@Service
390	public class ConsultaService {
391	
392	    private final Armazem armazem;
393	
394	    public ConsultaService(Armazem armazem) {
395	        this.armazem = armazem;
396	    }
397	
398	    public Produto produto(String sku) {
399	        return armazem.ler(estado -> {
400	            Produto produto = estado.produtos.get(sku);
401	            if (produto == null) {
402	                throw ErroNegocio.naoEncontrado("PRODUTO_NAO_ENCONTRADO");
403	            }
404	            return new Produto(produto.sku(), produto.nome(), produto.preco(), produto.pesoKg(),
405	                    produto.estoque(), produto.foraDeLinha());
406	        });
407	    }
408	
409	    public Cliente cliente(String cpf) {
410	        return armazem.ler(estado -> copia(clienteExistente(estado, cpf)));
411	    }
412	
413	    public List<Aviso> avisos(String cpf) {
414	        return armazem.ler(estado -> {
415	            clienteExistente(estado, cpf);
416	            return estado.avisosDoCliente(cpf).stream().map(ConsultaService::copia).toList();
417	        });
418	    }
419	
420	    public Aviso marcarLido(String id) {
421	        return armazem.escrever((estado, mudancas) -> {
422	            Aviso aviso = estado.avisos.get(id);
423	            if (aviso == null) {
424	                throw ErroNegocio.naoEncontrado("AVISO_NAO_ENCONTRADO");
425	            }
426	            if (!aviso.lido()) {
427	                aviso.marcarLido();
428	                mudancas.avisos.add(aviso);
429	            }
430	            return copia(aviso);
431	        });
432	    }
433	
434	    private static Cliente clienteExistente(Estado estado, String cpf) {
435	        Cliente cliente = estado.clientes.get(cpf);
436	        if (cliente == null) {
437	            throw ErroNegocio.naoEncontrado("CLIENTE_NAO_ENCONTRADO");
438	        }
439	        return cliente;
440	    }
441	
442	    private static Cliente copia(Cliente c) {
443	        return new Cliente(c.cpf(), c.email(), c.saldoCredito());
444	    }
445	
446	    private static Aviso copia(Aviso a) {
447	        return new Aviso(a.id(), a.seq(), a.cpf(), a.tipo(), a.pedidoId(), a.lido());
448	    }
449	}
450	package com.loja.persistencia;
451	
452	import org.slf4j.Logger;
453	import org.slf4j.LoggerFactory;
454	import org.springframework.beans.factory.annotation.Value;
455	import org.springframework.context.annotation.Bean;
456	import org.springframework.context.annotation.Configuration;
457	
458	import com.loja.dominio.Persistencia;
459	import com.loja.dominio.PersistenciaMemoria;
460	
461	@Configuration
462	public class ConfigPersistencia {
463	
464	    private static final Logger log = LoggerFactory.getLogger(ConfigPersistencia.class);
465	
466	    @Bean
467	    Persistencia persistencia(@Value("${app.db.url:}") String url, @Value("${app.db.user:}") String usuario,
468	                              @Value("${app.db.password:}") String senha) {
469	        if (url.isBlank()) {
470	            log.warn("DB_URL não definido: os dados ficarão só em memória e serão perdidos ao reiniciar");
471	            return new PersistenciaMemoria();
472	        }
473	        return new PersistenciaComEspera(new PgPersistencia(new PgConexao(url, usuario, senha)));
474	    }
475	
476	
477	    private static final class PersistenciaComEspera implements Persistencia {
478	
479	        private static final int TENTATIVAS = 30;
480	
481	        private final Persistencia destino;
482	
483	        PersistenciaComEspera(Persistencia destino) {
484	            this.destino = destino;
485	        }
486	
487	        @Override
488	        public com.loja.dominio.Estado carregar() {
489	            RuntimeException ultimo = null;
490	            for (int i = 1; i <= TENTATIVAS; i++) {
491	                try {
492	                    return destino.carregar();
493	                } catch (RuntimeException e) {
494	                    ultimo = e;
495	                    log.warn("Banco indisponível (tentativa {}/{}): {}", i, TENTATIVAS, e.getMessage());
496	                    try {
497	                        Thread.sleep(2_000);
498	                    } catch (InterruptedException ie) {
499	                        Thread.currentThread().interrupt();
500	                        break;
501	                    }
502	                }
503	            }
504	            throw ultimo;
505	        }
506	
507	        @Override
508	        public void gravar(com.loja.dominio.Mudancas mudancas) {
509	            destino.gravar(mudancas);
510	        }
511	    }
512	}

