     1	package com.loja.dominio;
     2	
     3	import java.util.ArrayList;
     4	import java.util.LinkedHashMap;
     5	import java.util.List;
     6	import java.util.Map;
     7	
     8	
     9	public class Estado {
    10	
    11	    public final Map<String, Produto> produtos = new LinkedHashMap<>();
    12	    public final Map<String, Cliente> clientes = new LinkedHashMap<>();
    13	    public final Map<String, Pedido> pedidos = new LinkedHashMap<>();
    14	    public final Map<String, Aviso> avisos = new LinkedHashMap<>();
    15	    private final Map<String, List<Pedido>> pedidosPorCpf = new LinkedHashMap<>();
    16	    private long ultimaSequenciaAviso;
    17	
    18	    public void adicionarPedido(Pedido pedido) {
    19	        pedidos.put(pedido.id(), pedido);
    20	        pedidosPorCpf.computeIfAbsent(pedido.cpf(), k -> new ArrayList<>()).add(pedido);
    21	    }
    22	
    23	    public List<Pedido> pedidosDoCliente(String cpf) {
    24	        return pedidosPorCpf.getOrDefault(cpf, List.of());
    25	    }
    26	
    27	    public void adicionarAviso(Aviso aviso) {
    28	        avisos.put(aviso.id(), aviso);
    29	        ultimaSequenciaAviso = Math.max(ultimaSequenciaAviso, aviso.seq());
    30	    }
    31	
    32	    public long proximaSequenciaAviso() {
    33	        return ++ultimaSequenciaAviso;
    34	    }
    35	
    36	    public List<Aviso> avisosDoCliente(String cpf) {
    37	        return avisos.values().stream()
    38	                .filter(a -> a.cpf().equals(cpf))
    39	                .sorted(java.util.Comparator.comparingLong(Aviso::seq))
    40	                .toList();
